import org.ghyura.cf.showcase.cucumber.GherkinCase;

/* checkout_cucumber (showcase-cucumber/01-gherkin-checkout): every test case is one Gherkin scenario against the bookshop's
   checkout engine, composed by the Combinatorics Framework. The heart of it is the timeline: the customer's four actions
   in one of their 24 orders, with up to two sudden events woven in after any action (a price rise, a duplicate delivery
   of the last request). Each data sheet adds its Given, When or Then (the values stay plain: FW_SheetNames wraps them
   into code); TAIL writes the scenario as a .feature file and runs it with Cucumber in this JVM. The first failing Then
   gives the verdict, the FW_EXIT_CODE of its own sheet, which FW_CUSTOM_VAR names; a failing Given or When gives 90. */
public class CheckoutCucumberCase {
    public static int FW_VAR = 0;
    static final GherkinCase g = new GherkinCase("Bookshop checkout: actions in every order, sudden events at every moment",
            "FW_REPLACE_ME_WITH_CURRENT_COMBO_SEQUENCE");

    /* A Then line with the verdict it gives when it fails. Its cell hands the sheet's exit code over through FW_VAR,
       which is taken back at once: the verdict is decided only after Cucumber has run. */
    static void then(String text, int code) {
        g.then(text, code);
        FW_VAR = 0;
    }

    public static void main(String[] args) {
        String folder = args.length > 0 ? args[0] : "showcase-cucumber/target/generated-features/01-gherkin-checkout";
        g.onStepFailure(90);
        g.fact("price_rise", "none");
        g.fact("duplicate", "none");

TAIL:
        GherkinCase.Outcome outcome = g.run(folder, "org.ghyura.cf.showcase.cucumber.checkout");
        FW_VAR = outcome.verdict();
        System.out.println("app=checkout_cucumber case=" + g.caseId() + " " + outcome.metricsText() + " FW_VAR=" + FW_VAR);
    }
}
